def solve(grid):
    n = len(grid)
    m = len(grid[0])
    out = [row[:] for row in grid]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 9:
                # The patterns are symmetric across the main diagonal
                if grid[j][i] != 9:
                    out[i][j] = grid[j][i]
                else:
                    # Fallback to anti-diagonal symmetry if both are 9
                    out[i][j] = grid[n - 1 - j][m - 1 - i]

    return out
